create table if not exists public.hg_wargame_rules (
  problem_id integer primary key check (problem_id between 1 and 50),
  command_signature text not null check (command_signature ~ '^[a-f0-9]{64}$'),
  updated_at timestamptz not null default now()
);

alter table public.hg_wargame_rules enable row level security;
revoke all on table public.hg_wargame_rules from public, anon, authenticated;

on conflict (problem_id) do update set command_signature = excluded.command_signature, updated_at = now();
